fn capitalize_first_letter(word: Vec<char>) -> Vec<char> {
    let mut result = word.clone(); // Create a new vector to hold the result

    if let Some(first_char) = result.get_mut(0) { // Get a mutable reference to the first character
        if first_char.is_lowercase() { // Check if the first character is lowercase
            *first_char = 'A'; // Replace it with 'A'
        } // If it's already uppercase, we leave it unchanged
    }

    result // Return the modified vector
}

fn main() {
    let input = vec!['b', 'e', 'a', 'r'];
    let output = capitalize_first_letter(input);
    println!("{:?}", output); // Output: ['A', 'e', 'a', 'r']
}